arguments.file_text:
@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>Shipment Dashboard</PageTitle>

<h2>Shipment Dashboard</h2>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" style="max-width: 300px;"
           placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        + New Shipment
    </button>
</div>

@if (showCreate)
{
    <div class="card mb-3 p-3">
        <h5>Create Shipment</h5>
        <div class="row g-2">
            <div class="col-md-3">
                <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-3">
                <input type="date" class="form-control" @bind="estimatedDeliveryDate" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Notes" @bind="newShipment.Notes" />
            </div>
        </div>
        <div class="mt-2">
            <button class="btn btn-success btn-sm" @onclick="CreateShipment">Create</button>
            <button class="btn btn-secondary btn-sm" @onclick="() => showCreate = false">Cancel</button>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Created</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadge(s.Status)">@s.Status</span>
                    </td>
                    <td>@s.CreatedAt.ToString("yyyy-MM-dd")</td>
                    <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto; display:inline-block;"
                                value="@s.Status"
                                @onchange="(e) => UpdateStatus(s, e.Value?.ToString())">
                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Exception">Exception</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private bool showCreate;
    private CreateShipmentDto newShipment = new();
