                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Exception">Exception</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private bool showCreate;
    private CreateShipmentDto newShipment = new();
    private DateTime? estimatedDeliveryDate;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm()
    {
        newShipment = new();
        estimatedDeliveryDate = null;
        showCreate = true;
    }

    private async Task CreateShipment()
    {
        newShipment.EstimatedDelivery = estimatedDeliveryDate;
        await ShipmentService.CreateShipmentAsync(newShipment);
        showCreate = false;
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus) || newStatus == shipment.Status) return;
        await ShipmentService.UpdateStatusAsync(shipment.Id, new UpdateShipmentStatusDto { Status = newStatus });
        shipment.Status = newStatus;
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Exception" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>Track My Shipments</PageTitle>

<h2>My Shipments</h2>

<div class="mb-4 card p-3">
    <h5>Track a Shipment</h5>
    <div class="d-flex gap-2">
        <input type="text" class="form-control" style="max-width:400px;"
               placeholder="Enter tracking number (e.g. SHP-20260612-A1B2C3D4)"
               @bind="trackingInput" @bind:event="oninput" />
        <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
    </div>

    @if (searchPerformed && trackedShipment is null)
    {
        <div class="alert alert-warning mt-2">No shipment found with that tracking number.</div>
    }
    @if (trackedShipment is not null)
    {
        <div class="alert alert-info mt-2">
            <strong>@trackedShipment.TrackingNumber</strong><br />
            Status: <span class="badge @GetStatusBadge(trackedShipment.Status)">@trackedShipment.Status</span><br />
            From: @trackedShipment.Origin → To: @trackedShipment.Destination<br />
            @if (trackedShipment.EstimatedDelivery.HasValue)
            {
                <span>Estimated Delivery: <strong>@trackedShipment.EstimatedDelivery.Value.ToString("yyyy-MM-dd")</strong></span>
            }
        </div>
    }
</div>

<h4>My Shipments</h4>

@if (myShipments is null)
{
    <p><em>Loading...</em></p>
}
else if (myShipments.Count == 0)
{
    <p class="text-muted">You have no shipments assigned to your account.</p>
}
else
{
    <div class="row">
        @foreach (var s in myShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h6 class="card-title"><code>@s.TrackingNumber</code></h6>
                        <p class="card-text mb-1">
                            <span class="badge @GetStatusBadge(s.Status)">@s.Status</span>
                        </p>
                        <p class="card-text mb-1">@s.Origin → @s.Destination</p>
                        @if (s.EstimatedDelivery.HasValue)
                        {
                            <p class="card-text"><small class="text-muted">
                                Est. Delivery: @s.EstimatedDelivery.Value.ToString("yyyy-MM-dd")
                            </small></p>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? myShipments;
    private string trackingInput = string.Empty;
    private ShipmentDto? trackedShipment;
    private bool searchPerformed;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await ShipmentService.GetMyShipmentsAsync();
    }

    private async Task TrackShipment()
    {
        searchPerformed = true;
        trackedShipment = null;
        if (!string.IsNullOrWhiteSpace(trackingInput))
        {
            trackedShipment = await ShipmentService.GetShipmentByTrackingAsync(trackingInput.Trim());
        }
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Exception" => "bg-danger",
        _ => "bg-secondary"
    };
}

